package dev.eugheist.tc4modern;
import net.minecraft.client.Minecraft;
import net.minecraft.client.model.geom.ModelLayerLocation;
import net.minecraft.client.renderer.*;
import net.minecraft.client.renderer.entity.*;
import net.neoforged.bus.api.SubscribeEvent;
import net.neoforged.fml.common.EventBusSubscriber;
@EventBusSubscriber(modid=TC4Modern.MODID,value=net.neoforged.api.distmarker.Dist.CLIENT,bus=EventBusSubscriber.Bus.MOD)
public final class OuterBossClient {
 static final ModelLayerLocation GOLEM=new ModelLayerLocation(AlchemyContent.id("eldritch_golem"),"main");
 @SubscribeEvent static void layers(net.neoforged.neoforge.client.event.EntityRenderersEvent.RegisterLayerDefinitions e){e.registerLayerDefinition(GOLEM,EldritchGolemModel::layer);}
 @SubscribeEvent static void renderers(net.neoforged.neoforge.client.event.EntityRenderersEvent.RegisterRenderers e){e.registerEntityRenderer(OuterBossContent.PORTAL.get(),CultistPortalRenderer::new);e.registerEntityRenderer(OuterBossContent.LEADER.get(),LeaderRenderer::new);e.registerEntityRenderer(OuterBossContent.GOLEM.get(),GolemRenderer::new);e.registerEntityRenderer(OuterBossContent.WARDEN.get(),WardenRenderer::new);}
 static final class LeaderRenderer extends HumanoidMobRenderer<CultistLeader,net.minecraft.client.model.HumanoidModel<CultistLeader>> {
  LeaderRenderer(EntityRendererProvider.Context c){super(c,new net.minecraft.client.model.HumanoidModel<>(c.bakeLayer(CrimsonRenderers.CULTIST_LAYER)),.5f);addLayer(new net.minecraft.client.renderer.entity.layers.HumanoidArmorLayer<>(this,new net.minecraft.client.model.HumanoidModel<>(c.bakeLayer(net.minecraft.client.model.geom.ModelLayers.PLAYER_INNER_ARMOR)),new net.minecraft.client.model.HumanoidModel<>(c.bakeLayer(net.minecraft.client.model.geom.ModelLayers.PLAYER_OUTER_ARMOR)),c.getModelManager()));}
  @Override public net.minecraft.resources.ResourceLocation getTextureLocation(CultistLeader e){return AlchemyContent.id("textures/models/cultist.png");}
  @Override protected void scale(CultistLeader e,com.mojang.blaze3d.vertex.PoseStack pose,float partial){pose.scale(1.25f,1.25f,1.25f);}
 }
 static final class GolemRenderer extends MobRenderer<EldritchGolem,EldritchGolemModel>{GolemRenderer(EntityRendererProvider.Context c){super(c,new EldritchGolemModel(c.bakeLayer(GOLEM)),.5f);}@Override public net.minecraft.resources.ResourceLocation getTextureLocation(EldritchGolem e){return AlchemyContent.id("textures/models/eldritch_golem.png");}@Override protected void scale(EldritchGolem e,com.mojang.blaze3d.vertex.PoseStack p,float partial){p.scale(2.15f,2.15f,2.15f);}@Override protected RenderType getRenderType(EldritchGolem e,boolean visible,boolean translucent,boolean glowing){return visible?RenderType.entityTranslucent(getTextureLocation(e)):super.getRenderType(e,visible,translucent,glowing);}}
 static final class WardenRenderer extends MobRenderer<EldritchWarden,EldritchGuardianModel<EldritchWarden>> {
  WardenRenderer(EntityRendererProvider.Context c){super(c,new EldritchGuardianModel<>(),.5f);addLayer(new net.minecraft.client.renderer.entity.layers.RenderLayer<EldritchWarden,EldritchGuardianModel<EldritchWarden>>(this){
   @Override public void render(com.mojang.blaze3d.vertex.PoseStack pose,MultiBufferSource buffers,int light,EldritchWarden e,float walk,float amount,float partial,float age,float yaw,float pitch){var eye=getParentModel().root.getChild("HoodEye");pose.pushPose();pose.scale(1.01f,1.01f,1.01f);eye.visible=true;eye.render(pose,buffers.getBuffer(RenderType.eyes(getTextureLocation(e))),(int)(210+Math.sin(e.tickCount/3f)*15),net.minecraft.client.renderer.texture.OverlayTexture.NO_OVERLAY);eye.visible=false;pose.popPose();}
  });}
  @Override public net.minecraft.resources.ResourceLocation getTextureLocation(EldritchWarden e){return AlchemyContent.id("textures/models/eldritch_warden.png");}
  @Override protected void scale(EldritchWarden e,com.mojang.blaze3d.vertex.PoseStack pose,float partial){pose.scale(1.5f,1.5f,1.5f);}
  @Override public void render(EldritchWarden e,float yaw,float partial,com.mojang.blaze3d.vertex.PoseStack pose,MultiBufferSource buffers,int light){pose.pushPose();pose.translate(0,-e.getBbHeight()*e.spawnTimer()/150f,0);super.render(e,yaw,partial,pose,buffers,light);pose.popPose();}
  @Override protected RenderType getRenderType(EldritchWarden e,boolean visible,boolean translucent,boolean glowing){return visible?RenderType.entityTranslucent(getTextureLocation(e)):super.getRenderType(e,visible,translucent,glowing);}
 }
 static void fieldEffects(net.minecraft.world.level.Level level,net.minecraft.core.BlockPos p){var r=level.random;float h=r.nextFloat()*.33f;Minecraft.getInstance().particleEngine.add(new ChampionSpark(p.getX()+r.nextFloat(),p.getY()+.1515+h/2,p.getZ()+r.nextFloat(),.3f-r.nextFloat()*.1f,0,.5f+r.nextFloat()*.2f));if(r.nextInt(50)==0)level.playLocalSound(p.getX(),p.getY(),p.getZ(),FociContent.sound("jacobs"),net.minecraft.sounds.SoundSource.BLOCKS,.5f,1+(r.nextFloat()-r.nextFloat())*.2f,false);}
 static void lockEffects(net.minecraft.core.BlockPos pos){var mc=Minecraft.getInstance();var r=mc.level.random;var spark=new ChampionSpark(pos.getX()+r.nextFloat(),pos.getY()+r.nextFloat(),pos.getZ()+r.nextFloat(),.65f+r.nextFloat()*.1f,1,1);spark.radius=.5f;spark.opacity=.8f;mc.particleEngine.add(spark);}
 static void wardenEffects(EldritchWarden e){var r=e.getRandom();if(e.spawnTimer()>0){float height=Math.max(1,e.getBbHeight()*(150-e.spawnTimer())/150f);for(int i=0;i<33;i++)Minecraft.getInstance().particleEngine.add(new SmokeSpiralParticle((net.minecraft.client.multiplayer.ClientLevel)e.level(),e.getX(),e.getY()+height/2,e.getZ(),height,r.nextInt(360),net.minecraft.util.Mth.floor(e.getY())-1,0x22112F));}Minecraft.getInstance().particleEngine.add(new GuardianClient.Wisp(e,e.getX()+(r.nextFloat()-r.nextFloat())*.2,e.getY()+e.getBbHeight()*.25,e.getZ()+(r.nextFloat()-r.nextFloat())*.2));}
 static void golemArc(EldritchGolem golem){if(golem.arcing>0)return;var r=golem.getRandom();float radius=2+r.nextFloat()*2;double angle=Math.toRadians(r.nextInt(360));var p=net.minecraft.core.BlockPos.containing(golem.getX()+radius*Math.cos(angle),golem.getY(),golem.getZ()+radius*Math.sin(angle));int count=0;while(count++<5&&golem.level().isEmptyBlock(p))p=p.below();if(golem.level().isEmptyBlock(p.above())&&!golem.level().isEmptyBlock(p)){golem.arcTarget=p;golem.arcing=8+r.nextInt(5);golem.playSound(FociContent.sound("jacobs"),.8f,1+(r.nextFloat()-r.nextFloat())*.05f);}}
 static void golemEffects(EldritchGolem golem){var level=(net.minecraft.client.multiplayer.ClientLevel)golem.level();var r=golem.getRandom();float angle=-golem.yBodyRot*(float)Math.PI/180-(float)Math.PI;var look=new net.minecraft.world.phys.Vec3(-Math.sin(angle),0,-Math.cos(angle));if(r.nextInt(20)==0)FociFx.sparkle(golem.getX()+look.x+(r.nextFloat()-r.nextFloat())/2,golem.getY()+golem.getEyeHeight()-.25,golem.getZ()+look.z+(r.nextFloat()-r.nextFloat())/2,.3f,0,0);level.addParticle(net.minecraft.core.particles.ParticleTypes.SMOKE,golem.getX()+look.x*.66,golem.getY()+golem.getEyeHeight()-.75,golem.getZ()+look.z*.66,0,.001,0);if(golem.arcing>0&&golem.arcTarget!=null){NodeBoltParticle.spawn(level,golem.getX(),golem.getY()+golem.getBbHeight()/2,golem.getZ(),golem.arcTarget.getX()+.5,golem.arcTarget.getY()+1,golem.arcTarget.getZ()+.5);golem.arcing--;}}
}
